run Positive1 {
    some disj E, X : Track | some disj S1 : Signal {
        Track = E + X
        Signal = S1
        Junction = none
        Entry = E
        Exit = X
        Semaphore = none
        Speed = S1
        signals = E->S1
        succs = E->X
    }
} for 2 Track, 1 Signal

run Positive2 {
    some disj E1, E2, J, X : Track | some disj S1, S2, S3 : Signal {
        Track = E1 + E2 + J + X
        Signal = S1 + S2 + S3
        Junction = J
        Entry = E1 + E2
        Exit = X
        Semaphore = S2
        Speed = S1 + S3
        signals = E1->S1 + E1->S2 + E2->S3
        succs = E1->J + E2->J + J->X
    }
} for 4 Track, 3 Signal

run Positive3 {
    some disj E1, E2, J, X1, X2 : Track | some disj S1, S2, S3, S4 : Signal {
        Track = E1 + E2 + J + X1 + X2
        Signal = S1 + S2 + S3 + S4
        Junction = J
        Entry = E1 + E2
        Exit = X1 + X2
        Semaphore = S3 + S4
        Speed = S1 + S2
        signals = E1->S1 + E2->S2 + E1->S3 + E2->S4
        succs = E1->J + E2->J + J->X1 + J->X2
    }
} for 5 Track, 4 Signal

run Negative1 {
    some disj E, X : Track | some disj S1, S2 : Signal {
        Track = E + X
        Signal = S1 + S2
        Junction = none
        Entry = E
        Exit = X
        Semaphore = S2
        Speed = S1
        signals = E->S1 + X->S2
        succs = E->X
    }
} for 2 Track, 2 Signal

run Negative2 {
    some disj E1, E2, J, X : Track | some disj S1, S2, S3 : Signal {
