        Signal = S1 + S2 + S3
        Junction = J
        Entry = E1 + E2
        Exit = X
        Semaphore = S3
        Speed = S1 + S2
        signals = E1->S1 + E2->S2 + J->S3
        succs = E1->J + E2->J + J->X
    }
} for 4 Track, 3 Signal

run Negative3 {
    some disj E1, E2, J, M, X : Track | some disj S1, S2, S3 : Signal {
        Track = E1 + E2 + J + M + X
        Signal = S1 + S2 + S3
        Junction = J
        Entry = E1 + E2
        Exit = X
        Semaphore = S3
        Speed = S1 + S2
